WITH valid AS (SELECT id, store_id, product_id, units, DATE_FORMAT(sale_date, 'MMM yyyy') AS sale_date_label, COALESCE(revenue, 0) AS revenue_filled FROM store_sales WHERE sale_date >= DATE '2023-04-13') SELECT id, store_id, sale_date_label, revenue_filled, ROW_NUMBER() OVER (PARTITION BY store_id, product_id ORDER BY units DESC, id) AS row_seq, AVG(units) OVER (PARTITION BY store_id) AS store_id_avg_units, LAG(units, 2) OVER (PARTITION BY product_id ORDER BY units, id) AS prev_units FROM valid;
